mapper.select:
SELECT M.*, R.RoleName, R.SvcCode
FROM wizardn.tAthMngr M
INNER JOIN wizardn.tAthRole R ON M.RoleUid = R.RoleUid

    AND M.MngrUid = #{pMngrUid}
    AND M.RoleUid = #{pRoleUid}
    AND M.LoginId = #{pLoginId}
    AND M.MngrName LIKE CONCAT('%',#{pMngrName},'%')

ORDER BY ${sidx} ${sord}

SELECT COUNT(*)
FROM wizardn.tAthMngr M
INNER JOIN wizardn.tAthRole R ON M.RoleUid = R.RoleUid

    AND M.MngrUid = #{pMngrUid}
    AND M.RoleUid = #{pRoleUid}
    AND M.LoginId = #{pLoginId}
    AND M.MngrName LIKE CONCAT('%',#{pMngrName},'%')

SELECT M.*, R.RoleName, R.SvcCode
FROM wizardn.tAthMngr M
INNER JOIN wizardn.tAthRole R ON M.RoleUid = R.RoleUid



            AND M.LoginId = #{pLoginId}

                AND R.SvcCode = (SELECT SvcCode FROM shopwizard.tCmpChnl WHERE ChnlCode = #{pChnlCode})

            AND M.Passwd = #{pPasswd}


            AND M.ShopCode = #{pShopCode}

SELECT IFNULL(ProdApprovYn, 0)
FROM wizardn.tAthMngr
WHERE LoginId = #{value}
